class Solution {
    public int[][] averageHeightOfBuildings(int[][] buildings) {
        TreeMap<Integer, long[]> ev = new TreeMap<>();
        for (int[] b : buildings) {
            long[] s = ev.computeIfAbsent(b[0], x -> new long[2]);
            s[0] += b[2]; s[1]++;
            long[] e = ev.computeIfAbsent(b[1], x -> new long[2]);
            e[0] -= b[2]; e[1]--;
        }
        List<int[]> res = new ArrayList<>();
        long sum = 0, cnt = 0;
        int prev = -1;
        for (Map.Entry<Integer, long[]> en : ev.entrySet()) {
            int pos = en.getKey();
            if (cnt > 0) {
                int avg = (int) (sum / cnt);
                int[] last = res.isEmpty() ? null : res.get(res.size() - 1);
                if (last != null && last[1] == prev && last[2] == avg) last[1] = pos;
                else res.add(new int[]{prev, pos, avg});
            }
            sum += en.getValue()[0];
            cnt += en.getValue()[1];
            prev = pos;
        }
        return res.toArray(new int[0][]);
    }
}
